GTF_IG_LONG = {"AN": {"AN": (0.39, 0.39), "HS": (0.43, 1.25), "FT": (0.43, 2.85)},
               "HS": {"AN": (1.25, 0.43), "HS": (1.17, 1.17), "FT": (1.25, 2.85)},
               "FT": {"AN": (2.85, 0.43), "HS": (2.85, 1.25), "FT": (2.71, 2.71)}}

MODES = ["四邊簡支", "三邊簡支(一邊自由)", "兩對邊簡支(另兩邊自由)", "一邊支承(懸臂)"]


# ---------------------------------------------------------------
# 四邊簡支:NFL 查表(AR 格點表,各等值線 log L 線性內插)
# ---------------------------------------------------------------
@st.cache_resource
def load4():
    raw = json.loads(NFL4_JSON)
    out = {}
    for t, lv in raw.items():
        c = {}
        for k, (v, e) in lv.items():
            c[float(k)] = (np.array(v, float), np.array(e, int))
        out[int(t)] = c
    return out


AR0, DAR, NG = 1.0, 0.05, 121


@st.cache_resource
def validate4():
    """資料驗證(與查表分開):逐長寬比檢查所有相鄰等值線對之順序與間距。回傳 {t: {AR 索引: [不合格等值線對 (k1,k2)]}}。"""
    ch_all = load4()
    bad = {}
    for t, ch in ch_all.items():
        bt = {}
        ks = sorted(ch)
        for gi in range(NG):
            prev = None
            for k in ks:
                d = float(ch[k][0][gi])
                if d <= 0:
                    continue
                if (not np.isfinite(d)) or (prev is not None and not (prev[1] > d * 1.0005)):
                    bt.setdefault(gi, []).append((prev[0] if prev else k, k))
                prev = (k, d)
        bad[t] = bt
    return bad


def lookup4(t, L, S):
    """回傳 (NFL kPa, 備註清單, 是否為估算)。估算 = 超出圖表或需外插,不可視為正式查表值。
    先由 validate4 驗證全部資料;查表時若所用之等值線對屬不合格資料,或間距為零/非有限,停止查表。"""
    ch = load4()[t]
    notes, est = [], False
    if L > X4_MAX[t] or S > S4_MAX:
        notes.append("尺寸超出圖表範圍"); est = True
    AR = L / S
    ARc = min(AR, AR0 + DAR * (NG - 1))
    if AR > ARc:
        notes.append("長寬比 > 7,以平延外插"); est = True
    x = (ARc - AR0) / DAR
    i0 = int(np.floor(x)); i1 = min(i0 + 1, NG - 1); w = x - i0
    badpairs = set(validate4()[t].get(i0, [])) | set(validate4()[t].get(i1, []))
    pts = []
    for k in sorted(ch):
        v, e = ch[k]
        a, b = v[i0], v[i1]
        if a <= 0 or b <= 0:
            continue
        d = float(np.exp((1 - w) * np.log(a) + w * np.log(b)))
        if AR > ARc:
            d *= AR / ARc
        pts.append((k, d, bool(e[i0] == 2 or e[i1] == 2)))
    if len(pts) < 2:
        return None, ["此長寬比下圖表資料不足,無法查表"], True

    # 凡 L 落入任何一對「順序顛倒/重疊」等值線所涵蓋的尺寸區間,即停止正式查表(不因另一對線能內插就視為有效)
    for p1, p2 in zip(pts, pts[1:]):
        if not (p1[1] > p2[1] * 1.0005):
            lo, hi = min(p1[1], p2[1]), max(p1[1], p2[1])
            if lo * 0.995 <= L <= hi * 1.005:
                return None, [f"資料檢核失敗(尺寸落入順序顛倒之等值線區間 {p1[0]:g}/{p2[0]:g} kPa),停止查表"], True

    def usable(p1, p2):
        return np.isfinite(p1[1]) and np.isfinite(p2[1]) and p1[1] > p2[1] and (p1[0], p2[0]) not in badpairs
    FAIL = (None, ["資料檢核失敗(此長寬比下所用等值線對順序/間距異常),停止查表"], True)
    lvl = sorted(ch)
    for p1, p2 in zip(pts, pts[1:]):
        (k1, d1, x1), (k2, d2, x2) = p1, p2
        if d1 >= L >= d2:
            if not usable(p1, p2):
                return FAIL
            wq = np.log(d1 / L) / np.log(d1 / d2)
            val = float(np.exp(np.log(k1) + wq * (np.log(k2) - np.log(k1))))
            if lvl.index(k2) - lvl.index(k1) > 1:
                notes.append("相鄰等值線資料缺漏,以前後等值線內插(內插結果列為估算)"); est = True
            if x1 or x2:
                notes.append("等值線尾段超出圖表右緣,以短邊不變平延"); est = True
            return (val, notes, est) if np.isfinite(val) else FAIL
    est = True
    if L > pts[0][1]:
        p1, p2 = pts[0], pts[1]
        if not usable(p1, p2):
            return FAIL
        (k1, d1, _), (k2, d2, _) = p1, p2
        s_ = np.log(k2 / k1) / np.log(d2 / d1)
        notes.append(f"低於圖表最低等值線({k1:g} kPa),外插")
        return float(np.exp(np.log(k1) + s_ * np.log(L / d1))), notes, est
    p1, p2 = pts[-2], pts[-1]
    if not usable(p1, p2):
        return FAIL
    (k1, d1, _), (k2, d2, _) = p1, p2
    s_ = np.log(k2 / k1) / np.log(d2 / d1)
    notes.append(f"高於圖表最高可靠等值線({k2:g} kPa),外插")
    return float(np.exp(np.log(k2) + s_ * np.log(L / d2))), notes, est


# ---------------------------------------------------------------
# 三邊簡支:NFL 查表  (P = 垂直自由邊之支承邊長度;F = 自由邊長度;須 P/F ≥ 0.5)
# ---------------------------------------------------------------
@st.cache_resource
def load3():
    raw = json.loads(NFL3_JSON)
    return {int(t): {float(k): (np.array(p, float), np.array(f, float)) for k, (p, f) in lv.items()}
            for t, lv in raw.items()}


def _lookup3(t, P, F):
    ch = load3()[t]
    notes, est = [], False
    if F > 2 * P + 1e-6:
        return None, ["P/F < 0.5,超出標準適用範圍(§3.2.2)"], True
    if F > F3_MAX[t]:
        notes.append("自由邊長度超出圖表範圍"); est = True
    Pe = min(P, P3_MAX)
    if P > P3_MAX:
        notes.append("平行邊長度超出圖表,以右緣平延估算"); est = True
    Fk = {}
    for k, (p, f) in ch.items():
        if Pe >= p[0]:
            Fk[k] = float(np.interp(Pe, p, f))
    pts = sorted([(f, k) for k, f in Fk.items()], key=lambda x: -x[0])
    for a, b in zip(pts, pts[1:]):
        if not (a[1] < b[1] and a[0] > b[0]):
            return None, ["相鄰等值線順序異常(資料檢核失敗),停止查表"], True
    # 對角線(F = 2P)錨點:各等值線起點。起點須「承載力愈大、P 愈小」;違反者剔除並標為估算,不以排序掩蓋
    ks = sorted(ch)
    anchors, dropped = [], []
    for k in sorted(ks, reverse=True):          # 由高載重(小 P)往低載重檢查
        p0 = float(ch[k][0][0])
        if anchors and not (p0 > anchors[-1][0] * 1.001):
            dropped.append(k); continue
        anchors.append((p0, k))
    anchors.sort()
    ap = np.log([a[0] for a in anchors]); ak = np.log([a[1] for a in anchors])
    lpv = np.log(P)
    dext = not (ap[0] <= lpv <= ap[-1])
    if dext:
        n = min(3, len(ap))
        c = np.polyfit(ap[:n], ak[:n], 1) if lpv < ap[0] else np.polyfit(ap[-n:], ak[-n:], 1)
        nd = float(np.exp(np.polyval(c, lpv)))
    else:
        nd = float(np.exp(np.interp(lpv, ap, ak)))
    if len(pts) == 0:
        notes.append("此 P 值下無等值線通過,僅由對角線趨勢估算"); return nd, notes, True
    allp = [(f, q, False) for f, q in pts]
    allp.append((2 * P, nd, True))
    allp.sort(key=lambda x: -x[0])
    merged = []                                   # 相同 F 之點:承載力一致則合併,不一致則停止
    for pt in allp:
        if merged and abs(merged[-1][0] - pt[0]) <= 1e-3 * pt[0]:
            if abs(np.log(merged[-1][1] / pt[1])) > 0.02:
                return None, ["相同尺寸點之承載力不一致(資料檢核失敗),停止查表"], True
            merged[-1] = (merged[-1][0], merged[-1][1], merged[-1][2] and pt[2])
        else:
            merged.append(pt)
    allp = merged
    for pt in allp:                                # 命中點直接回傳
        if abs(pt[0] - F) <= 1e-3 * F:
            if pt[2]:
                notes.append("對角線端點依各等值線起點推算,為估算"); est = True
            return float(pt[1]), notes, est or dext
    if len(allp) < 2:
        return None, ["資料點不足,無法查表"], True
    for a, b in zip(allp, allp[1:]):
        if not (a[1] <= b[1] * 1.0005 or a[2] or b[2]):
            return None, ["相鄰等值線順序異常(資料檢核失敗),停止查表"], True
    for (f1, q1, d1), (f2, q2, d2) in zip(allp, allp[1:]):
        if f1 >= F >= f2 and f1 > f2 and q2 > q1 * 0.999:
            w = np.log(f1 / F) / np.log(f1 / f2)
            val = float(np.exp(np.log(q1) + w * (np.log(q2) - np.log(q1))))
            if d1 or d2:
                notes.append("近對角線區間依各等值線起點(對角線)推算,為估算"); est = True
            if dext:
                est = True
            if dropped and (d1 or d2):
                notes.append("對角線起點資料有順序異常點,已剔除(" + ", ".join(f"{k:g}" for k in dropped) + " kPa),不作正式判定")
                est = True
            return val, notes, est
        if f1 >= F >= f2 and f1 > f2:
            return None, ["對角線與等值線之順序異常(資料檢核失敗),停止查表"], True
    est = True
    if F > allp[0][0]:
        (f1, q1, _), (f2, q2, _) = allp[0], allp[1]
        notes.append("低於圖表最低等值線,外插")
    else:
        (f1, q1, _), (f2, q2, _) = allp[-2], allp[-1]
        notes.append("高於圖表最高等值線,外插")
    if f1 == f2 or q1 <= 0 or q2 <= 0:
        return None, ["外插點重合,無法查表"], True
    s_ = np.log(q2 / q1) / np.log(f2 / f1)
    return float(np.exp(np.log(q1) + s_ * np.log(F / f1))), notes, est


def lookup3(t, P, F):
    r = _lookup3(t, P, F)
    if r[0] is None:
        return r
    if not (np.isfinite(r[0]) and r[0] > 0):
        return None, ["計算結果非有限正數,無法判定"], True
    return r


# ---------------------------------------------------------------
# 三邊簡支線性板理論(Lévy 級數,自由邊):回傳每 1 kPa 之最大撓度 (mm) 與最大拉應力 (MPa)
#   a = 自由邊長度 F(兩平行支承邊之間距),b = 平行支承邊長度 P
# ---------------------------------------------------------------
def _basis(al, b, y):
    u = al * y; v = al * (b - y); eu = np.exp(-u); ev = np.exp(-v)
    f = np.array([eu, u * eu, ev, v * ev])
    d2 = np.array([al**2 * eu, al**2 * (u - 2) * eu, al**2 * ev, al**2 * (v - 2) * ev])
    d1 = np.array([-al * eu, al * (1 - u) * eu, al * ev, -al * (1 - v) * ev])
    d3 = np.array([-al**3 * eu, al**3 * (3 - u) * eu, al**3 * ev, -al**3 * (3 - v) * ev])
    return f, d1, d2, d3


def levy3(a, b, t, nu=0.3, nterm=121, ny=25):
    q = 1e-3          # 1 kPa = 1e-3 MPa
    D = E_GLASS * t**3 / (12 * (1 - nu**2))
    ys = np.linspace(0, b, ny)
    Wy = np.zeros(ny); Wxx = np.zeros(ny); Wyy = np.zeros(ny)
    for m in range(1, nterm + 1, 2):
        al = m * np.pi / a; qm = 4 * q / (m * np.pi); Yp = qm / (D * al**4)
        f0, _, b0, _ = _basis(al, b, 0.0)
        fb, ab, bb, cb = _basis(al, b, b)[0], _basis(al, b, b)[1], _basis(al, b, b)[2], _basis(al, b, b)[3]
        M = np.array([f0, b0, bb - nu * al**2 * fb, cb - (2 - nu) * al**2 * ab])
        co = np.linalg.solve(M, np.array([-Yp, 0.0, nu * al**2 * Yp, 0.0]))
        s = np.sin(al * a / 2)
        for i, y in enumerate(ys):
            f, _, d2, _ = _basis(al, b, y)
            Yv = Yp + co @ f
            Wy[i] += Yv * s; Wxx[i] += -al**2 * Yv * s; Wyy[i] += (co @ d2) * s
    Mx = -D * (Wxx + nu * Wyy); My = -D * (Wyy + nu * Wxx)
    sig = 6 * np.maximum(Mx, My) / t**2
    return float(Wy.max()), float(sig.max())


# ---------------------------------------------------------------
# 四邊簡支變形:Appendix X1(大變形近似式);X1 不適用(雙重對數引數 ≤ 1)時改用線性小變形理論
# ---------------------------------------------------------------
def deflection4(L, S, q_kpa, t):
    """回傳 (採用變形 mm, 說明, 線性解 mm, X1 值 mm 或 None)。
    線性小變形解 w_lin 在 w_lin ≤ t 時採用(此區 X1 不適用,實測會出現載重增加而變形反減);
    w_lin > t 進入非線性區後採 min(X1, 線性解),並以 t 為下限,使結果對載重單調、連續。"""
    ab = min(L / S, 5.0)
    arg = q_kpa * (L * S) ** 2 / (E_GLASS * 1000 * t**4)
    alpha = float(np.interp(ab, ALPHA_AR, ALPHA_V))
    w_lin = alpha * 12 * (1 - 0.22**2) * (q_kpa / 1000) * S**4 / (E_GLASS * t**3)   # α 為 w=α q b⁴/D 之係數
    w_x1 = None
    if arg > 1.0:
        r0 = 0.553 - 3.83 * ab + 1.11 * ab**2 - 0.0969 * ab**3
        r1 = -2.29 + 5.83 * ab - 2.17 * ab**2 + 0.2067 * ab**3
        r2 = 1.485 - 1.908 * ab + 0.815 * ab**2 - 0.0822 * ab**3
        x = np.log(np.log(arg))
        w_x1 = float(t * np.exp(r0 + r1 * x + r2 * x**2))
    if w_lin <= t or w_x1 is None:
        return w_lin, "線性小變形理論(w ≤ t,X1 不適用)", w_lin, w_x1
    w = max(min(w_x1, w_lin), t)
    return w, ("Appendix X1(非線性區,以 t 為下限)" if w_x1 <= w_lin else "線性小變形理論(X1 大於線性解,取線性)"), w_lin, w_x1


